-- Migration 0039_proceedings: generated by drizzle-kit (tables, keys, indexes), RLS, the column-list SET NULL action, the scope guard and the cycle guard hand-written, reviewed before commit.
-- Reviewed-by: Claude (agent, #346)
-- Proceedings (#346, part 3 of #32; ADR 0013):
--   * proceeding, proceeding_link: tenant tables (tenantTable()) under FORCE RLS with ws_isolation
--     (tenantPolicy()), carrying provenance() and provenanceCheck(). Grants come from the default
--     privileges (app: 02-roles.sql, clerk: 0022).
--   * Case identity: unique (workspace_id, forum_id, case_type_code, number, year) once numbered and
--     (workspace_id, cnr) when set; number and year are required from numbered on; cnr is 16
--     upper-case alphanumerics; case_type_code is stored normalised (upper-case, no dots or spaces).
--   * proceeding.forum_id is a single-column FK into the global-or-workspace forum table, guarded by
--     app_reference_scope_guard in mode same_or_global (a catalogue forum or the workspace's own).
--   * matter_id and the provenance anchor_id are composite NO ACTION FKs; parent_proceeding_id is
--     ON DELETE SET NULL (parent_proceeding_id) (Postgres 15+): drizzle-kit writes a plain SET NULL,
--     which would also null the NOT NULL workspace_id; its snapshot keeps `set null`.
--   * app_proceeding_link_cycle_guard(): BEFORE INSERT/UPDATE trigger function rejecting (23514) a
--     parent_of link that would close a cycle. It walks the parent_of edges from the new child as the
--     invoker (links never cross workspaces: composite FKs), after taking a per-workspace advisory
--     transaction lock so two concurrent inserts cannot each miss the other's edge.
-- Expand only: new tables, a function and triggers.
CREATE TABLE "proceeding" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"matter_id" uuid NOT NULL,
	"forum_id" uuid NOT NULL,
	"kind" "proceeding_kind" DEFAULT 'main' NOT NULL,
	"case_type_code" text NOT NULL,
	"case_type_raw" text,
	"number" text,
	"year" integer,
	"sr_no" text,
	"fr_no" text,
	"diary_no" text,
	"filing_no" text,
	"cnr" text,
	"filing_date" date,
	"state" "proceeding_state" DEFAULT 'filed' NOT NULL,
	"state_changed_at" timestamp with time zone DEFAULT now() NOT NULL,
	"parent_proceeding_id" uuid,
	"title_petitioner" text,
	"title_respondent" text,
	"source_type" "source_type" NOT NULL,
	"source_ref" text,
	"anchor_id" uuid,
	"confidence" numeric(4, 3),
	"confirmation_state" "confirmation_state" DEFAULT 'proposed' NOT NULL,
	"captured_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "proceeding_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "proceeding_provenance_chk" CHECK ((source_type = 'manual' or anchor_id is not null or source_ref is not null) and (confidence is null or (confidence >= 0 and confidence <= 1))),
	CONSTRAINT "proceeding_numbered_chk" CHECK (state not in ('numbered', 'disposed') or (number is not null and year is not null)),
	CONSTRAINT "proceeding_number_chk" CHECK (number is null or btrim(number) <> ''),
	CONSTRAINT "proceeding_year_chk" CHECK (year is null or (year >= 1800 and year <= 2200)),
	CONSTRAINT "proceeding_cnr_chk" CHECK (cnr is null or cnr ~ '^[A-Z0-9]{16}$'),
	CONSTRAINT "proceeding_case_type_code_chk" CHECK (case_type_code <> '' and case_type_code = upper(case_type_code) and case_type_code !~ '[.[:space:]]'),
	CONSTRAINT "proceeding_not_parent_of_self_chk" CHECK (parent_proceeding_id is null or parent_proceeding_id <> id)
);
--> statement-breakpoint
CREATE TABLE "proceeding_link" (
	"id" uuid PRIMARY KEY DEFAULT gen_random_uuid() NOT NULL,
	"from_proceeding_id" uuid NOT NULL,
	"to_proceeding_id" uuid NOT NULL,
	"kind" text NOT NULL,
	"source_type" "source_type" NOT NULL,
	"source_ref" text,
	"anchor_id" uuid,
	"confidence" numeric(4, 3),
	"confirmation_state" "confirmation_state" DEFAULT 'proposed' NOT NULL,
	"captured_at" timestamp with time zone DEFAULT now() NOT NULL,
	"created_at" timestamp with time zone DEFAULT now() NOT NULL,
	"updated_at" timestamp with time zone DEFAULT now() NOT NULL,
	"workspace_id" uuid NOT NULL,
	CONSTRAINT "proceeding_link_workspace_id_id_uq" UNIQUE("workspace_id","id"),
	CONSTRAINT "proceeding_link_triple_uq" UNIQUE("workspace_id","from_proceeding_id","to_proceeding_id","kind"),
	CONSTRAINT "proceeding_link_provenance_chk" CHECK ((source_type = 'manual' or anchor_id is not null or source_ref is not null) and (confidence is null or (confidence >= 0 and confidence <= 1))),
	CONSTRAINT "proceeding_link_kind_chk" CHECK (kind in ('parent_of', 'connected', 'appeal_from', 'lower_court')),
	CONSTRAINT "proceeding_link_not_self_chk" CHECK (from_proceeding_id <> to_proceeding_id)
);
