CREATE FUNCTION app_proceeding_link_cycle_guard() RETURNS trigger
  LANGUAGE plpgsql SECURITY INVOKER SET search_path = public, pg_temp
  AS $$
  BEGIN
    IF NEW.kind <> 'parent_of' THEN
      RETURN NEW;
    END IF;
    PERFORM pg_advisory_xact_lock(hashtextextended('proceeding_link:' || NEW.workspace_id::text, 0));
    IF EXISTS (
      WITH RECURSIVE descendant(id) AS (
        SELECT NEW.to_proceeding_id
        UNION
        SELECT l.to_proceeding_id
          FROM proceeding_link l
          JOIN descendant d ON l.from_proceeding_id = d.id
         WHERE l.workspace_id = NEW.workspace_id
           AND l.kind = 'parent_of'
           AND l.id <> NEW.id
      )
      SELECT 1 FROM descendant WHERE id = NEW.from_proceeding_id
    ) THEN
      RAISE EXCEPTION 'proceeding_link: parent_of % -> % would close a cycle',
        NEW.from_proceeding_id, NEW.to_proceeding_id
        USING ERRCODE = 'check_violation';
    END IF;
    RETURN NEW;
  END
  $$;--> statement-breakpoint
CREATE TRIGGER "proceeding_link_parent_of_cycle_guard" BEFORE INSERT OR UPDATE OF workspace_id, "from_proceeding_id", "to_proceeding_id", "kind" ON "proceeding_link" FOR EACH ROW EXECUTE FUNCTION app_proceeding_link_cycle_guard();--> statement-breakpoint
